if(!$classes) { echo '<div class="notice">Tidak ada cakupan Guru Piket pada tanggal ini. Penugasan khusus diberikan admin tanpa hak Admin penuh.</div>'; return; }
if($classId!==null && !in_array($classId,array_map('intval',array_column($classes,'id_kelas')),true))deny_access();
