<?php
$displayClasses=array_values(array_filter($classes,fn($c)=>($classId===null || (int)$c['id_kelas']===$classId)&&($major===null || (int)$c['id_jurusan']===$major)));
$classTotal=count($displayClasses);[$classPage,$classPages,$classOffset]=crud_page_bounds($classTotal,6);
foreach(array_slice($displayClasses,$classOffset,6)as $class):
 $cid=(int)$class['id_kelas']; $rows=ak_daily_roster($cid,$periodId,$date);$expected=ak_day_schedules($cid,$periodId,$date);$filled=count(array_filter($expected,fn($x)=>$x['id_pertemuan']!==null));
 $preview=ak_reconciliation_preview($cid,$periodId,$date);$hashes=[];foreach($preview as $p)$hashes[$p['nis']]=$p['evidence_hash'];
 $stale=count(array_filter($rows,fn($r)=>$r['id_harian'] && ($r['evidence_hash']??'')!==($hashes[$r['nis']]??'')));
?><section class="panel"><h2><?=e($class['nama_kelas'])?></h2><p>Sesi terisi: <strong><?=e($filled)?> / <?=count($expected)?></strong> · <?=$filled===count($expected) && count($expected)>0?'Seluruh sesi sudah terisi':'Belum lengkap / belum ada jadwal'?> · <?=count($rows)?> siswa</p><?php if(!ak_school_day($period,$date)):?><p class="muted">Bukan hari efektif. Tidak ada kewajiban pengisian harian.</p><?php endif;if($stale):?><div class="notice"><?=e($stale)?> data harian memiliki bukti sesi yang berubah. Perlu peninjauan; rekap belum ditimpa.</div><?php endif;ak_summary_cards(ak_summary($rows));
ak_exports('harian',['id_kelas'=>$cid,'id_tahun_ajaran'=>$periodId,'mulai'=>$date,'selesai'=>$date]);
if(current_user()['role']!=='kepala_sekolah'):?><form method="post"><?=csrf_field()?><?php ak_hidden('action','rekonsiliasi');ak_hidden('id_kelas',$cid);ak_hidden('id_tahun_ajaran',$periodId);ak_hidden('tanggal',$date);ak_field('alasan','Alasan / hasil pemeriksaan rekonsiliasi');?><button type="submit">Rekonsiliasi dari bukti seluruh sesi</button></form><?php endif;?>
<details><summary>Daftar siswa & koreksi (H/S/I/A/Belum)</summary><?php foreach($rows as $row):?><div class="history-entry"><strong><?=e($row['nomor_absen'])?>. <?=e($row['nama_siswa'])?></strong><p><?=e(AK_STATUSES[$row['status']])?> · <?=e($row['keterangan']??'Belum ada data harian terverifikasi')?></p>
<?php if($row['id_harian'] && ak_duty_allowed($cid,$periodId,$date,true)):?><details><summary>Koreksi dengan alasan</summary><form method="post"><?=csrf_field()?><?php ak_hidden('action','koreksi_harian');ak_hidden('id',$row['id_harian']);ak_hidden('revision',$row['revision']);ak_hidden('id_kelas',$cid);ak_hidden('id_tahun_ajaran',$periodId);ak_hidden('tanggal',$date);ak_select('status','Status',AK_STATUSES,$row['status']);ak_field('keterangan','Keterangan',$row['keterangan']);ak_field('alasan','Alasan koreksi wajib');?><button type="submit">Simpan koreksi</button></form></details><?php endif;?></div><?php endforeach;?></details>
<details><summary>Riwayat rekonsiliasi dan koreksi</summary><?php $history=ak_rows("SELECT r.*,u.username,h.nis FROM ak_riwayat r JOIN ak_absensi_harian h ON r.entity='harian' AND r.record_id=CAST(h.id AS CHAR) JOIN users u ON u.id_user=r.actor_id WHERE h.id_kelas=? AND h.id_tahun_ajaran=? AND h.tanggal=? ORDER BY r.id DESC LIMIT 100",[$cid,$periodId,$date]);foreach($history as $row):?><p class="history-entry"><?=e($row['created_at'])?> · <?=e($row['username'])?> · <?=e($row['action'])?> · NIS <?=e($row['nis'])?><?php $before=json_decode($row['sebelum']??'null',true);$after=json_decode($row['sesudah']??'null',true);?><br>Status <?=e($before['status']??'Belum direkap')?> → <?=e($after['status']??'B')?><br><?=e($row['alasan'])?></p><?php endforeach;?></details></section><?php endforeach;crud_pager($classPage,$classPages,$classTotal,'kelas');?>
